import http from "node:http";
import { toNodeHandler } from "better-auth/node";
import { auth } from "./auth";
import { requireUser } from "./auth/session";
import { handleChat, handleChatHistory, listAgents, sendJson } from "./chat-api";
import { createWebHandler } from "./web";

const authHandler = toNodeHandler(auth);

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);

  if (req.method === "GET" && url.pathname === "/health") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ status: "ok" }));
    return;
  }

  // Better Auth endpoints (sign-in, sign-out, session)
  if (url.pathname === "/api/auth" || url.pathname.startsWith("/api/auth/")) {
    try {
      await authHandler(req, res);
    } catch (error: unknown) {
      console.error("Auth request failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Auth failed" });
      else res.end();
    }
    return;
  }

  // Current user
  if (url.pathname === "/api/me") {
    if (req.method !== "GET") {
      res.writeHead(405, { allow: "GET" }).end();
      return;
    }
    const user = await requireUser(req, res);
    if (!user) return;
    sendJson(res, 200, { user });
    return;
  }

  // Web chat API
  if (url.pathname === "/api/agents") {
    if (req.method !== "GET") {
      res.writeHead(405, { allow: "GET" }).end();
      return;
    }
    const user = await requireUser(req, res);
    if (!user) return;
    sendJson(res, 200, listAgents(user));
    return;
  }

  const historyMatch = url.pathname.match(/^\/api\/chat\/([^/]+)\/history$/);
  if (historyMatch) {
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      await handleChatHistory(decodeURIComponent(historyMatch[1]), req, res, user);
    } catch (error: unknown) {
      console.error("Chat history failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Chat history failed" });
      else res.end();
    }
    return;
  }

  const chatMatch = url.pathname.match(/^\/api\/chat\/([^/]+)$/);
  if (chatMatch) {
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      await handleChat(decodeURIComponent(chatMatch[1]), req, res, user);
    } catch (error: unknown) {
      console.error("Web chat failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Chat failed" });
      else res.end();
    }
    return;
  }

  if (url.pathname === "/api" || url.pathname.startsWith("/api/")) {
    res.writeHead(404).end();
    return;
  }

  // Everything else is the web UI (Vite dev middleware, or web/dist in production).
  webHandler(req, res);
});

const webHandler = await createWebHandler(server);

const PORT = Number(process.env.PORT) || 3000;
server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});

import { resolve } from "node:path";
import Database from "better-sqlite3";
import { betterAuth } from "better-auth";
import { admin, username } from "better-auth/plugins";
import { dataDir } from "../data-dir";
import { roles } from "./roles";

export const auth = betterAuth({
  appName: "nlhack",
  secret: process.env.BETTER_AUTH_SECRET,
  baseURL: process.env.BETTER_AUTH_URL ?? "http://localhost:3000",
  database: new Database(resolve(dataDir(), "auth.db")),
  // Users are created only by the seed script via the admin API.
  emailAndPassword: { enabled: true, disableSignUp: true },
  plugins: [
    username(),
    admin({ roles, defaultRole: "employee", adminRoles: ["admin"] }),
  ],
});

export type Session = typeof auth.$Infer.Session;
export type Role = "admin" | "employee";
import type { IncomingMessage, ServerResponse } from "node:http";
import { fromNodeHeaders } from "better-auth/node";
import { auth, type Role } from "./index";

export type SessionUser = { id: string; name: string; username: string; role: Role };

// Resolve the signed-in user from the request cookies, or null.
export async function getSessionUser(req: IncomingMessage): Promise<SessionUser | null> {
  const session = await auth.api.getSession({ headers: fromNodeHeaders(req.headers) });
  if (!session) return null;
  const { id, name, username, role } = session.user;
  return { id, name, username: username ?? "", role: role as Role };
}

// Route guard: send 401/500 and return null when there is no usable session.
// Responds inline (not via chat-api's sendJson) to keep the auth module free of mastra imports.
export async function requireUser(req: IncomingMessage, res: ServerResponse): Promise<SessionUser | null> {
  let user: SessionUser | null;
  try {
    user = await getSessionUser(req);
  } catch (error: unknown) {
    console.error("Session lookup failed", error);
    res.writeHead(500, { "content-type": "application/json; charset=utf-8" });
    res.end(JSON.stringify({ error: "Session lookup failed" }));
    return null;
  }
  if (!user) {
    res.writeHead(401, { "content-type": "application/json; charset=utf-8" });
    res.end(JSON.stringify({ error: "Unauthorized" }));
  }
  return user;
}
import { mkdirSync } from "node:fs";
import { resolve } from "node:path";

// Absolute DATA_DIR (default ./data), created on first use; shared by auth.db and mastra.db.
export function dataDir(): string {
  const dir = resolve(process.cwd(), process.env.DATA_DIR ?? "./data");
  mkdirSync(dir, { recursive: true });
  return dir;
}
# Model Provider (DeepSeek used by Mastra agents)
DEEPSEEK_API_KEY=

# NeatLogs Observability & Tracing (also authenticates the Neatlogs Agent's MCP connection)
NEATLOGS_API_KEY=
# Optional: defaults to https://ingest.neatlogs.com
NEATLOGS_ENDPOINT=https://ingest.neatlogs.com
NEATLOGS_DEBUG=false

# Crustdata Market Research Tools
CRUSTDATA_API_KEY=

# GitHub agent (fine-grained PAT; read scopes to inspect, write scopes to make approved changes; used against GitHub's remote MCP server)
GITHUB_PAT=

# Server Port (optional, defaults to 3000)
PORT=3000

# Auth (Better Auth) — generate a secret with: openssl rand -base64 32
BETTER_AUTH_SECRET=
# Public origin of the app (cookies + CSRF checks are tied to it)
BETTER_AUTH_URL=http://localhost:3000
# Directory for SQLite files (auth.db, later mastra.db); defaults to ./data
DATA_DIR=./data
